classes-invariants.code:
class Ticket {
    static int issued = 0;
    final int number;

    Ticket() {
        issued++;
        number = issued;
    }
}

// in main:
new Ticket();
new Ticket();
Ticket t = new Ticket();
System.out.println(t.number + " " + Ticket.issued);

